    },
    {
      "keystrokes": "cat /outputs/report.json\n",
      "duration": 0.1
    },
    {
      "keystrokes": "ffprobe -v quiet -print_format json -show_streams /outputs/tts_segments/seg_0.wav | jq '.streams[0] | {sample_rate, channels, duration}'\n",
      "duration": 0.5
    },
    {
      "keystrokes": "ffprobe -v quiet -print_format json -show_streams /outputs/dubbed.mp4 | jq '.streams[] | select(.codec_type==\"audio\") | {sample_rate, channels, codec_name}'\n",
      "duration": 0.5
    }
  ],
  "task_complete": false
}

